wikidata_queries.styles:
SELECT DISTINCT ?espnId ?player ?bowlingStyleLabel WHERE {
  ?player wdt:P2697 ?espnId; wdt:P2545 ?bowlingStyle.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

wikidata_queries.venues:
SELECT DISTINCT ?espnId ?ground ?country ?countryLabel ?isoCode WHERE {
  ?ground wdt:P3572 ?espnId; wdt:P17 ?country.
  OPTIONAL { ?country wdt:P297 ?isoCode. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
